role = 'assistant'

    AND (username LIKE CONCAT('%', #{username}, '%') OR user_id LIKE CONCAT('%', #{username}, '%'))


    AND model LIKE CONCAT('%', #{model}, '%')


    AND create_time >= #{startTime}


